from pathlib import Path
import re
text=Path('tmp/pdfs/page-22.txt').read_text()
part11, part12=text.split('XLMR Continued Pretraining (SIB200)')
for name, block in [('Table 11', part11), ('Table 12', part12)]:
    rows=[]
    for line in block.splitlines():
        if re.match(r'"'^[a-z]{2,3}'"\\s', line):
            vals=[float(v) for v in re.findall(r'(\\d\\.\\d+)\\s*±', line)]
            if len(vals)==4:
                rows.append((line.split()[0], vals))
    print(name, 'rows:', len(rows))
    print('Column means:', [round(sum(v[c] for _,v in rows)/len(rows),4) for c in range(4)])
    if name=='Table 12':
        last=[v for lang,v in rows if lang in ['mi','mni','pag']]
        print('Final tier column means:', [round(sum(v[c] for v in last)/len(last),4) for c in range(4)])
for i in [21,22]:
    print('Page',i)
    text=Path(f'tmp/pdfs/page-{i:02d}.txt').read_text()
    matches=0; rows=0
    for line in text.splitlines():
        if re.match(r'"'^[a-z]{2,3}'"\\s', line):
            sds=re.findall(r'±\\s*(\\d\\.\\d+)',line)
            if len(sds)==4:
                rows+=1
                matches+=(sds[0]==sds[2] if i==21 or 'XLMR' not in text[:text.index(line)] else sds[1]==sds[3])
    print('Rows with raw and heuristic equal reported uncertainties:', matches, '/', rows)
